pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function testFuzz_property(bool transferSucceeds) public {
        RecordingForeignToken token = new RecordingForeignToken(transferSucceeds);
        bool ok = true;
        try c.withdrawForeignTokens(address(token)) returns (bool ret) {
            ok = (ret == transferSucceeds);
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract RecordingForeignToken {
    bool public immutable succeeds;
    uint256 public balance;
    bool public called;
    uint256 public recordedAmount;

    constructor(bool _succeeds) {
        succeeds = _succeeds;
    }

    function mint(uint256 amount) external {
        balance = amount;
    }

    function balanceOf(address) external view returns (uint256) {
        return balance;
    }

    function transfer(address, uint256 amount) external returns (bool) {
        called = true;
        recordedAmount = amount;
        return succeeds;
    }
}
